#nullable enable

using Alba;
using Campaigns.Slices.Campaigns;
using Campaigns.Views;
using Marten;
// WaitForNonStaleProjectionDataAsync is an extension in Marten.Events.TestingExtensions.
using Marten.Events;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Journeys;

/// <summary>
/// a campaign opened, a message queued, a delivery recorded
///
/// Walks: open-campaign -> queue-message -> record-outcome
/// Ends:  CampaignDashboard(status=Open, queued=1, delivered=1, bounced=0)
///
/// THE ONE RULE. Every step goes through the REAL API, in order, and nothing here appends an event. No
/// setup helper, no session.Events.Append, no seeding between steps. A slice's GWT is allowed to append its
/// history because history is exactly what a GIVEN means; a journey may not, because the whole point is
/// whether step two can live on what step one actually left behind.
///
/// WHAT THIS CATCHES that no slice test can: an id minted in one shape and read in another, a projection
/// current for its own slice and stale for the next, a rule that only bites on the SECOND command in a
/// sequence. All three pass a green per-slice suite.
///
/// AND NOTE WHICH SLICE IS NOT HERE. close-campaign is drawn in column 2, beside open-campaign, because
/// they share the Campaign stream — but the story closes last, so a journey including it would run right to
/// left and `journey-runs-backward` says so. That warning is the model telling you its columns are grouped
/// by stream while its story runs in another order. Neither is wrong; it is worth knowing.
/// </summary>
public sealed class CampaignLifecycleJourneyTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static readonly TimeSpan DaemonTimeout = TimeSpan.FromSeconds(20);

    [Fact]
    public async Task CampaignLifecycle()
    {
        var campaignId = Guid.NewGuid();
        var messageId = Guid.NewGuid();
        var senderId = Guid.NewGuid();
        const string recipient = "a@example.com";

        // STEP 1 — open-campaign. The first and only step that invents an id; everything after it must
        // live on what this one left behind, which is the whole test.
        await WhenPosting(x =>
        {
            x.Post.Json(new OpenCampaign(campaignId, "January newsletter")).ToUrl(OpenCampaignEndpoint.Route);
            x.StatusCodeShouldBe(204);
        });

        // STEP 2 — queue-message, against the campaign step 1 opened. Its rule "a message cannot be queued
        // to a closed campaign" is enforced against the stream, so this is the first thing in the suite that
        // proves the two slices share a world rather than each having their own.
        var (_, queued) = await WhenPosting(x =>
        {
            x.Post.Json(new QueueMessage(messageId, campaignId, senderId, "January newsletter", [recipient]))
                .ToUrl(QueueMessageEndpoint.Route);
            x.StatusCodeShouldBe(200);
        });

        // AND STEP 3 USES THE ID THE API HANDED BACK, not the one this test made up. That distinction is the
        // whole "an id minted in one shape and read in another" failure class: assert on your own variable
        // and the test cannot see a slice that echoes something subtly different. Reading it out of the
        // response is what makes this a journey rather than three requests in a row.
        var issued = queued.ReadAsJson<QueuedMessage>()!;
        issued.MessageId.ShouldBe(messageId);

        // STEP 3 — record-outcome, against the message step 2 queued. "an outcome for a recipient not on the
        // message is refused" reads the recipient list off the stream, so a wrong recipient shape between
        // slices fails HERE and nowhere else.
        await WhenPosting(x =>
        {
            x.Post.Json(new RecordOutcome(issued.MessageId, recipient, "delivered", null))
                .ToUrl($"/messages/{issued.MessageId}/outcome");
            x.StatusCodeShouldBe(204);
        });

        // WAIT FOR THE DAEMON, AND THIS LINE COST A FAILURE TO LEARN.
        //
        // WhenPosting wraps every request in Wolverine's ExecuteAndWaitAsync, which blocks until all
        // CASCADING MESSAGE work is done — so a journey ending on an Inline view can assert immediately, and
        // most of this project's tests do. CampaignDashboard is registered Async, and Wolverine's tracking
        // knows nothing about Marten's async daemon.
        //
        // The first version of this test asserted straight away and failed with Queued == 1 and
        // Delivered == 0 — not zero for both, which is the tell: the daemon had caught up as far as step 2's
        // event and not step 3's. A journey is the longest gap between a first write and a final assertion in
        // the whole suite, so it is where this bites hardest and where it is easiest to misread as a
        // composition bug.
        await Store.WaitForNonStaleProjectionDataAsync(DaemonTimeout);

        // THEN — the model's outcome for this journey, asserted through the read side. CampaignDashboard is
        // a MultiStreamProjection: the campaign counts come from the Campaign stream and the queued/delivered
        // counts from Message streams, so this single assertion is also the one place the two stream types
        // are proved to roll up onto one row after a real sequence rather than a hand-appended one.
        await using var session = Store.QuerySession();
        var dashboard = await session.LoadAsync<CampaignDashboard>(campaignId);

        dashboard.ShouldNotBeNull();
        dashboard.Status.ShouldBe(CampaignDashboard.Open);
        dashboard.Queued.ShouldBe(1);
        dashboard.Delivered.ShouldBe(1);
        dashboard.Bounced.ShouldBe(0);
    }
}
